int dvb_diseqc_send_master_cmd(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
        int i, rc;

        if (d->msg_len < 1 || d->msg_len > 6)
                return -EINVAL;

        if (dvb_debug & DVB_FE_DEBUG)
                printk(KERN_DEBUG "DiSEqC: sending master command: ");

        for (i = 0; i < d->msg_len; i++)
                if (dvb_debug & DVB_FE_DEBUG)
                        printk(" %02x", d->msg[i]);
        if (dvb_debug & DVB_FE_DEBUG)
                printk("\n");

        d->cmd_len = d->msg_len;
        d->tx_toneBURST = 1;

        rc = fe->ops.set_voltage(fe, SEC_VOLTAGE_13);
        if (rc < 0)
                return rc;

        msleep(50);

        rc = fe->ops.send_burst(fe, SECTONE_BURST_A);
        if (rc < 0)
                return rc;

        rc = fe->ops.send_diseqc_msg(fe, d);
        if (rc < 0)
                return rc;

        msleep(50);

        return 0;
}

int dvb_send_diseqc_master_msg(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int ret = 0;
	int i;

	/* Validate message length */
	if (d->msg[0] < 2 || d->msg[0] > 6) {
		return -EINVAL;
	}

	d->length = d->msg[0];

	/* Log message if debugging is enabled */
#ifdef CONFIG_DVB_DISEQC_DEBUG
	printk(KERN_DEBUG "DiSEqC message: ");
	for (i = 0; i < d->length; i++)
		printk("0x%02x ", d->msg[i]);
	printk("\n");
#endif

	/* Set toneburst type */
	if (d->msg[1] & 0x01)
		fe->ops.release_toneburst(fe, 1);
	else
		fe->ops.release_toneburst(fe, 0);

	/* Wait for LNB to be ready */
	if (fe->ops.set_toneburst) {
		ret = fe->ops.set_toneburst(fe, 1);
		if (ret < 0)
			return ret;
	}

	/* Delay for voltage stabilization */
	msleep(50);

	/* Send the message */
	if (fe->ops.send_master_cmd) {
		ret = fe->ops.send_master_cmd(fe, d);
		if (ret < 0)
			return ret;
	}

	/* Wait for the message to be sent */
	if (d->msg[1] & 0x01)
		msleep(200);
	else
		msleep(100);

	return 0;
}

int dvb_send_diseqc_master_msg(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int rc = 0;

	if (d->msg_len < 1 || d->msg_len > 6)
		return -EINVAL;

	if (dvb_debug & 4) {
		int i;
		printk(KERN_DEBUG "DiSEqC: sending master command ");
		for (i = 0; i < d->msg_len; i++)
			printk("0x%02x ", d->msg[i]);
		printk("\n");
	}

	d->msg[0] &= 0x7f;
	d->msg[0] |= 0x80;

	d->msg_len = 6;

	d->cmdtype = DVB_DISEQC_TONEBURST_A;

	msleep(50);

	rc = fe->ops.send_diseqc_master_cmd(fe, d);

	msleep(100);

	return rc;
}

int dvb_diseqc_send_master_cmd(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int rc = 0;

	if (d->msg[0] > DVB_DISEQC_MAX_MSG_LEN)
		return -EINVAL;

	if (dvb_debug & DVB_FE)
	 printk(KERN_DEBUG "DISEQC: sending master command: %*ph\n", d->msg[0], d->msg);

	d->msg[1] = 0x00; /* command length */
	d->msg[2] = 0x30; /* toneburst type A */

	/* Wait for LNB to be ready */
	msleep(50);

	/* Allow voltage to stabilize */
	udelay(100);

	rc = fe->ops.send_diseqc_msg(fe, d->msg);
	if (rc)
		return rc;

	/* Wait for message to be sent */
	msleep(50);

	return 0;
}

int dvb_send_diseqc_master_msg(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int i, rc;
	u8 msg_len;

	if (d->msg[0] != 0x10 && d->msg[0] != 0x18 && d->msg[0] != 0x28)
		return -EINVAL;

	msg_len = d->msg[1] & 0x0f;
	if (msg_len > 6)
		return -EINVAL;

	if (msg_len < 6) {
		for (i = 2; i < 6; i++)
			d->msg[i] = 0;
	}

	if (fe->ops.send_master_cmd)
		rc = fe->ops.send_master_cmd(fe, d);
	else
		rc = -EOPNOTSUPP;

	return rc;
}
